 b['code_references']=['lib/product-catalog.ts:279 availableAddOns; :315 selectedComponents; :343 resolveCatalogFacts','lib/catalog-enrichment.ts:74 selectedScopedAddOns; :188–258 document priority','lib/catalog-product-comparison.ts:190 materializeCatalogProduct; :220 valueForKey','lib/insurance-normalization.ts:460 normalizeTermName; :505 normalizeCatalogTermKey']
