canonical=[]
def cd(cid,bids,kind,keys,definition,why,comparison,customer,risk,requirement):
 canonical.append(dict(decision_id=cid,batch_ids=bids,classification=kind,keys=keys,semantic_definition=definition,why_existing_structure_fails_or_suffices=why,affected_products=list(dict.fromkeys(p for bid in bids for p in byid[bid]['affected_products'])),affected_families=list(dict.fromkeys(f for bid in bids for f in byid[bid]['affected_families'])),source_evidence=list(dict.fromkeys(s for bid in bids for s in byid[bid]['source_evidence'])),comparison_behavior=comparison,customer_mode_implication=customer,false_equivalence_risk=risk,regression_requirements=requirement))
cd('CD-015',['B-015'],'CANONICAL_GAP',['flytting.tyveri_skadeverk.grense'],'Tap ved tyveri/skadeverk under flytting med eksplisitt utførerscope og per-skadetilfelle-grense. Term, ikke generell transportskadedekning.','Generell transport/bæring, tyveri utenfor hjem og uhell er ikke samme hendelse. Ny presis child-key i eksisterende flytting-familie er nok; ingen schemautvidelse.','Egen rad; ikke match mot transportskade. Motpart uten egen dokumentasjon blir unknown.','Eksakt dokumentfact har forrang; aldri global alias av gammel transportnøkkel.','Privat flytting kan få feil 30 000-tak; profesjonelt tyveri kan bli oppfattet som generell transportskade.',['Utfører og hendelse beholdt','Ingen cross-provider remapping','Dokumentprioritet med gamle og presise keys'])
cd('CD-017-021',['B-017','B-021'],'EXISTING_KEYS_REUSED',['reise.forsinkelse.avgang_sum','reise.forsinkelse.fremmote_sum','reise.forsinkelse.rute','reise.bagasje.forsinket'],'Avgang: avtalt transport går ikke som planlagt. Fremmøte: kunden når ikke planlagt transport. Beløp for hotell/transport beholdes kvalifisert; samme key betyr samme hendelsesfamilie, ikke identisk vilkår.','Eksisterende Tryg-nøkler og tekstlige CatalogFact verdier kan bevare trigger, person/hendelse og hotell/transport. Ingen ny scalar-beløpsmodell er nødvendig for disse batchene.','To egne rader under eksisterende Forsinkelse; hele kvalifiserte verdier sammenlignes, aldri bare 1 500 mot 20 000 uten trigger. Betinget utilgjengelig bagasje beholdes med egen kilde som del av bagasjetermen.','Ingen one-to-many alias fra rute. Dokumentert uspesifisert rute må konservativt blokkere nye undergrense-fills som kan stride mot dokumentet.','24 timer må ikke flyttes til fremmøte/hotell; Fremtinds samlede 6 000 må ikke bli 6 000 per utgiftstype.',['Separate hendelsesgrenser','Standard/Super-arv','Dokument X > katalog Y','Ingen Eika-migrering'])
cd('CD-018',['B-018'],'EXISTING_KEYS_COMPOSITION_FIX',['hund.bruksverdi.dekning','hund.bruksverdi.grense','hund.bruksverdi.alder','hund.bruksverdi.begrensning','dyr.liv.dekning'],'Frende Bruksverdi er et betinget innhold i valgt Tap, ikke kjøpbart separat produkt.','Eksisterende keys og komponentmekanisme er tilstrekkelige for fakta; delt seleksjonsguard fra CD-022-SELECT er nødvendig for kundemodus.','Optional via Tap i produktmodus. Valgt Tap materialiserer betingede child facts; ingen egen valgfri Bruksverdi-pakke.','Bruksverdi-evidens alene må ikke produsere Liv/Tap-valg. Bare avslag på Bruksverdi må ikke fjerne øvrig Tap.','Frende inklusjon må ikke bli samme arkitekturregel som Gjensidige valgfritt Bruk→Liv.',['Tap-only dekning','Child selection/not_selected uten parent escalation','Katt-isolasjon','Under 8 år mot livsopphør ved hovedforfall etter 10'])
cd('CD-019',['B-019'],'EXISTING_KEY_REUSED',['reise.overnatting'],'Generell adgang for dagstur/reise uten overnatting. YES for dagstur; NO for et generelt overnattingskrav; ikke NOT_COVERED.','Nøkkelen finnes allerede. Mangel er katalogplassering, ikke manglende produktkunnskap eller behov for ny state-enum.','Samme rad som Tryg; termtekst med egen kilde. Ingen UI-utledning fra geografi.','Overnattingsvilkår for spesifikke fordeler er uavhengige av generell trip eligibility.','Generell dagstur kan feilaktig frigjøre leiebil/avbestilling fra vilkår; Tryg tjenestereise kan kopieres.',['OVERNIGHT-01','Standard/Super begge veier mot Tryg Ekstra/Premium','Leiebil og arrangementsavbestilling beholdt'])
cd('CD-020',['B-020'],'CANONICAL_GAP',['hus.skadedyr.dyr.bekjempelse','hus.skadedyr.dyr.bygningsskade','hus.skadedyr.insekter.bekjempelse','hus.skadedyr.insekter.bygningsskade','hus.skadedyr.insekter.egenandel'],'To søsken etter skadevoldergruppe, hver med handling/ytelse. Dyr betyr kildens mus/rotter/andre dyr med egne unntak, ikke bare gnagere; insekter betyr kildebestemte skadeinsekter.','Generiske keys får replacesBase og included-preferanse til å slå sammen/fjerne ulike ytelser. Nye child keys er nok; ingen ny product inheritance-motor.','Egne presise rader under eksisterende Råte og skadedyr. Ingen tvungen ekvivalens til andre provideres brede pest-facts. Standard inkludert dyr + optional insekter; Pluss begge.','Presise avslag og dokumentfakta for hver gren isoleres. Bred skadedyrregel bevares uten å tolkes som to sikre valg.','Mus/rotter≠insekter; bekjempelse≠materialnedbrytning; lukt/isolasjon≠kun råte; insektegenandel må ikke brukes for alle dyr.',['Standard uten/med tillegg/Pluss','Ingen inherited fact loss','Optional vises selv med inkludert søsken','Dokument X>Y, artsgrenisolasjon'])
cd('CD-022-DEP',['B-022'],'CANONICAL_GAP',['CatalogAddOn.requiresAddOnIds'],'Optional all-of liste over tillegg som eksplisitt må være valgt for en gyldig katalogkombinasjon. Krever ikke automatisk kundeseleksjon.','requiresLevel gjelder hovedprodukt. exclusiveGroup er gjensidig utelukkelse, ikke avhengighet. Produktarv ville uriktig gjøre Bruk inkludert i Liv.','Katalogmodus viser conditional optional med dependency-evidens; den kan materialisere en mulig pakke uten kundeseleksjon.','Streng manuell validering. PDF dokumentfakta beholdes selv ved ufullstendig/konfliktende avhengighet; bare avhengig katalogberikelse blokkeres.','En dependency closure kan auto-velge Liv; sykler/dangling eller cross-scope referanser kan gi feil produkter.',['Ingen/Bruk/Liv/Liv+Bruk','Cycle/self/dangling/cross-scope/version negatives','Product materialization vs customer selection','Selected/not_selected/unknown/conflict'])
cd('CD-022-SELECT',['B-022','B-018'],'CANONICAL_GAP',['CatalogAddOn.selectionEvidenceKeys'],'Eksplisitt hvilke canonical parent-keys som kan velge eller blokkere hele tilleggskomponenten; øvrige faktanøkler er innhold/underdekninger. Eksakt navngitt dokumentvalg er fortsatt mulig.','selectedScopedAddOns utleder alle parent keys fra faktalisten og bruker alle som valg-/avslagsbevis. Dette blander produktkomposisjon og individuell seleksjon.','Ingen ny fact/rad; kun trygg materialisering/valg. Fravær av metadata bevarer dagens kompatibilitet.','Tap kan velges av dokumentert Tap/Liv, ikke av en Bruksverdi-child; Bruksverdi-avslag fjerner bare child, ikke resten av Tap.','Child→parent escalation og child-avslag→parent-avslag. Katalogtekst må aldri være dokumentevidens.',['Explicit parent selected + child not_selected','Child selected + parent unknown/not_selected','Unchanged addons without metadata','No array-order dependence'])
cd('CD-022-CAT',['B-022'],'CANONICAL_GAP',['katt.bruksverdi.dekning','katt.bruksverdi.alder','katt.bruksverdi.begrensning'],'Katt: dokumentert tap av avlsegenskaper innen forsikret bruksområde, betinget av eget Bruk-valg og Liv.','Katt-register mangler Bruk. hund.bruksverdi gjelder hund og blir avvist eller feilsemantisk på katt. Ingen ny generell dyr-liv-fact kan erstatte artsdistinksjonen.','Egen Katt Bruksverdi-undergruppe innen eksisterende produktvisning; ingen Hund↔Katt-akse. Other-cat unknown er ikke not covered.','Katt Bruk-facts krever dokumentvalg; behold fullvilkårets terskel/varighet som betingelser, ikke vurder individets egnethet.','50 % arbeidshund må ikke bli kattens avlsterskel; Liv 13 år må ikke bli Bruk 10 år.',['Species isolation','Cat100% versus dog work50%','Bruk expiry vs Liv','PDF/document priority and source-page separation'])

